MERGE `{{params.project_name}}.semantics_central.Bookings` final
USING (
{{range_query}}
) staging
ON final.booking_id = staging.booking_id
WHEN MATCHED THEN
UPDATE SET
final.external_id = staging.external_id,
final.booking_appointment_date = staging.booking_appointment_date,
final.booking_location = staging.booking_location,
final.place_id = staging.place_id,
final.inspection_center_city = staging.inspection_center_city,
final.inspection_center_name = staging.inspection_center_name,
final.booking_status = staging.booking_status,
final.booking_status_internal = staging.booking_status_internal,
final.booking_comments = staging.booking_comments,
final.booking_source = staging.booking_source,
final.cancelled_in_status = staging.cancelled_in_status,
final.call_status = staging.call_status,
final.discarded_reason = staging.discarded_reason,
final.assigned_to = staging.assigned_to,
final.assigned_to_name = staging.assigned_to_name,
final.cancellation_reason = staging.cancellation_reason,
final.rejection_reason = staging.rejection_reason,
final.cancelled_at = staging.cancelled_at,
final.booking_type = staging.booking_type,
final.booking_created = staging.booking_created,
final.booking_last_modified = staging.booking_last_modified,
final.deleted_at = staging.deleted_at,
final.booking_channel = staging.booking_channel,
final.lead_id = staging.lead_id,
final.customer_id = staging.customer_id,
final.country_id = staging.country_id,
final.created_by = staging.created_by
WHEN NOT MATCHED THEN
INSERT (
booking_id,
external_id,
booking_appointment_date,
booking_location,
place_id,
inspection_center_city,
inspection_center_name,
booking_status,
booking_status_internal,
booking_comments,
booking_source,
cancelled_in_status,
call_status,
discarded_reason,
assigned_to,
assigned_to_name,
cancellation_reason,
rejection_reason,
cancelled_at,
booking_type,
booking_created,
booking_last_modified,
deleted_at,
booking_channel,
lead_id,
customer_id,
country_id,
created_by
) VALUES (
staging.booking_id,
staging.external_id,
staging.booking_appointment_date,
staging.booking_location,
staging.place_id,
staging.inspection_center_city,
staging.inspection_center_name,
staging.booking_status,
staging.booking_status_internal,
staging.booking_comments,
staging.booking_source,
staging.cancelled_in_status,
staging.call_status,
staging.discarded_reason,
staging.assigned_to,
staging.assigned_to_name,
staging.cancellation_reason,
staging.rejection_reason,
staging.cancelled_at,
staging.booking_type,
staging.booking_created,
staging.booking_last_modified,
staging.deleted_at,
staging.booking_channel,
staging.lead_id,
staging.customer_id,
staging.country_id,
staging.created_by
)